#' Second overall sasonality test from \insertCite{Maravall2012;textual}{sautilities}.
#'
#' Conduct the second overall test for seasonality as laid out in 
#' \insertCite{Maravall2012;textual}{sautilities}.
#'
#' Version 6.0, 2026-04-14
#'
#' @param seas_obj \code{seas} object generated by the \code{seasonal} package 
#'        \insertCite{seasonal2018}{sautilities}.
#'        This is a required entry.
#' @param this_ar_spec_cv List object with two elements - 99 and 95 percent critical 
#'        values for the frequencies of the AR(30) spectrum as generated by the 
#'        \code{gen_ar_spec_cv} function.
#' @param n_sim integer scalar; number of simulations; this option is used only if
#'        \code{this_ar_spec_cv} is not specified.
#'        Default is 100000.
#' @param this_series Character string; the table used to generate the AR(30) spectrum. 
#'        Default is \code{"b1"}.
#' @param this_ori_qs Character string; code for which original series QS will 
#'        be used in this analysis. 
#'        Default is \code{"qssorievadj"} (original series adjusted for extreme values, short span); 
#'        other choices are \code{"qsori"} (original series, full span), 
#'        \code{"qsorievadj"} (original series adjusted for extreme values, full span), and 
#'        \code{"qssori"} (original series, short span).
#'        For more information on the QS statistic, 
#'        see \insertCite{Bell2022;textual}{sautilities}.
#' @param take_log Logical scalar; indicates if the AR spectrum is generated 
#'        from the log of the data. 
#'        Default is \code{TRUE}.
#' @param take_diff Logical scalar; indicates if the data is differenced before 
#'        the AR spectrum is generated. Default is \code{TRUE}.
#' @param use_seasonal Logical scalar; if TRUE, the \code{seasonal} regressor 
#'        is used; otherwise, use the sine-cosine trignonmetric regressors 
#'        generated by \code{sincos}.
#' @return A list with 5 elements: \code{QStest} (test probability for QS), 
#'         \code{NPtest} (test probability for NP), 
#'         \code{Ftest} (test probability for model based seasonal F-test), 
#'         \code{spectrum} (character string with test result - possible values of either 
#'         \code{"evidence of seasonal peak"}, \code{"no evidence of seasonal peak"}),
#'         and \code{result} (character string with test result - possible values of either
#'         \code{"strong seasonal"}, \code{"weak seasonal"}, \code{"no seasonal"}.
#'
#' @author Brian C. Monsell, \email{monsell.brian@@bls.gov} or \email{bcmonsell@@gmail.com}
#'
#' @references
#'  \insertAllCited{}
#'
#' @examples
#' air_seas <- 
#'    seasonal::seas(AirPassengers,
#'       series.save = "b1",
#'       transform.function = "log",
#'       arima.model="(0 1 1)(0 1 1)",
#'       forecast.maxlead = 36, 
#'       slidingspans = "")
#' ar30_spec_cv <- gen_ar_spec_cv(1000, 97, 12)
#' second_test <- overall_seasonal_test_2(air_seas, ar30_spec_cv)
#' @importFrom Rdpack reprompt
#' @export
overall_seasonal_test_2 <- 
   function(seas_obj = NULL, 
            this_ar_spec_cv = NULL, 
			n_sim = 100000,
            this_series = "b1", 
            this_ori_qs = "qssorievadj",
            take_log = TRUE, 
            take_diff = TRUE, 
            use_seasonal = TRUE) {
    # Author: Brian C. Monsell (OEUS) Version 6.0, 2026-04-14

    # check if a value is specified for \code{seas_obj}
    if (is.null(seas_obj)) {
        stop("must specify a seas object")
    } else {
    # check if a seas object is specified for \code{seas_obj}
        if (!inherits(seas_obj, "seas")) {
           stop("First argument must be a seas object")
        }
    }
    
    this_x <- seasonal::series(seas_obj, this_series)
    if (take_log) { this_x <- log(this_x) }

    this_NP     <- NP_test(this_x)
    this_QS     <- 1.0 - as.vector(seasonal::udg(seas_obj, this_ori_qs))[2]
    
    this_spectrum_test <- 
	    combined_spectrum_test(seas_obj, 
		    this_ar_spec_cv = this_ar_spec_cv, 
			n_sim = n_sim,
			this_series = this_series,
            take_log = take_log, 
			take_diff = take_diff)
    if (this_spectrum_test) {
        this_spectrum_peak <- "evidence of seasonal peak"
    }
    else {
        this_spectrum_peak <- "no evidence of seasonal peak"
    }
    this_F      <- get_seasonal_ftest_prob(seas_obj, this_series, use_seasonal)

    this_result <- "no evidence"
    if ((this_QS > 0.99 & this_F > 0.95) | (this_QS > 0.95 & this_F > 0.99)) {
        this_result <- "strong evidence"
    } else {
        if (this_QS < 0.99 & this_F < 0.99) {
            this_result <- "no evidence"
        } else {
            if (this_QS > 0.99) {
                if ((this_F < 0.99) | (this_NP$cv < 0.99) | (!this_spectrum_test)) {
                    this_result <- "weak evidence"
                }
            }
            if (this_F > 0.99) {
                if ((this_QS < 0.99) | (this_NP$cv < 0.99) | (!this_spectrum_test)) {
                    this_result <- "weak evidence"
                }
            }
        }
    }

    return(list(QStest = this_QS, NPtest = this_NP$cv, Ftest = this_F, 
                spectrum = this_spectrum_peak, result = this_result))
}
